INSERT INTO sources (episode_id, episode_slug, sort_order, title, url, publisher, domain, published_date, description, quote, turn_index, timestamp_seconds, timestamp_label, http_status, verified_at) VALUES ((SELECT id FROM episodes WHERE slug = 'california-high-speed-rail-and-the-billionaire-tax'), 'california-high-speed-rail-and-cap-and-trade', 1, 'Proposition 1A: Safe, Reliable High-Speed Passenger Train Bond Act — Official Voter Information Guide & Text of Proposed Law (2008)', 'https://vig.cdn.sos.ca.gov/2008/general/pdf-guide/suppl-complete-guide.pdf', 'California Secretary of State', 'vig.cdn.sos.ca.gov', NULL, 'Official November 2008 supplemental voter guide containing the statutory text of AB 3034 (Proposition 1A) authorizing $9.95 billion in general obligation bonds for a 220 mph San Francisco–to–Los Angeles high-speed train system.', 'Voters approved Prop 1A in two thousand eight for about ten billion in bonds, promising San Francisco to Los Angeles in under three hours at two hundred twenty miles an hour by twenty twenty.', 1, 9.0, '00:09', 200, '2026-10-24T18:08:00Z')
