INSERT INTO sources (episode_id, episode_slug, sort_order, title, url, publisher, domain, published_date, description, quote, turn_index, timestamp_seconds, timestamp_label, http_status, verified_at) VALUES ((SELECT id FROM episodes WHERE slug = 'california-high-speed-rail-and-the-billionaire-tax'), 'california-high-speed-rail-and-cap-and-trade', 2, 'California High-Speed Rail 2026 Draft Business Plan', 'https://hsr.ca.gov/wp-content/uploads/2026/02/2026-HSR-Draft-Business-Plan-02282026.pdf', 'California High-Speed Rail Authority', 'hsr.ca.gov', NULL, 'The Authority''s February 2026 draft business plan detailing $15.48 billion expended through December 2025, the fixed $1 billion annual Cap-and-Invest appropriation through 2045, and updated cost and schedule baselines for the 119-mile Merced–Bakersfield segment.', 'He locked in a billion a year through twenty forty-five, dropped Buy American to get Siemens trains faster, and is courting private partners.', 5, 265.0, '04:25', 200, '2026-10-24T18:08:00Z')
