INSERT INTO source_spans (source_id, turn_index, start_offset, end_offset, quote) VALUES ((SELECT id FROM sources WHERE episode_id = (SELECT id FROM episodes WHERE slug = 'california-high-speed-rail-and-the-billionaire-tax') AND url = 'https://hsr.ca.gov/wp-content/uploads/2026/02/2026-HSR-Draft-Business-Plan-02282026.pdf'), 5, 648, 789, 'He locked in a billion a year through twenty forty-five, dropped Buy American to get Siemens trains faster, and is courting private partners.')
INSERT INTO source_spans (source_id, turn_index, start_offset, end_offset, quote) VALUES ((SELECT id FROM sources WHERE episode_id = (SELECT id FROM episodes WHERE slug = 'california-high-speed-rail-and-the-billionaire-tax') AND url = 'https://hsr.ca.gov/wp-content/uploads/2026/02/2026-HSR-Draft-Business-Plan-02282026.pdf'), 21, 32, 262, 'Of the fifteen point five billion spent through December twenty twenty-five, about fourteen point eight billion went to capital — actual building, land, equipment. Roughly seven hundred million was pure administration and support.')
INSERT INTO sources (episode_id, episode_slug, sort_order, title, url, publisher, domain, published_date, description, quote, turn_index, timestamp_seconds, timestamp_label, http_status, verified_at) VALUES ((SELECT id FROM episodes WHERE slug = 'california-high-speed-rail-and-the-billionaire-tax'), 'california-high-speed-rail-and-cap-and-trade', 3, 'Board Memo: Construction Package 2-3 Omnibus Settlement & Change Order 427 with Dragados-Flatiron Joint Venture', 'https://hsr.ca.gov/wp-content/uploads/2026/04/2026-04-29-Agenda-Item-7-CP-2-3-Board-Memo-V1-A11Y.pdf', 'California High-Speed Rail Authority', 'hsr.ca.gov', NULL, 'Official April 2026 HSRA board briefing for Agenda Item #7 approving the $537.3 million omnibus Change Order 427 with Dragados-Flatiron Joint Venture on the 65-mile Construction Package 2-3 corridor.', 'It''s Change Order four twenty-seven with Dragados Flatiron Joint Venture, finalized May twenty-first, twenty twenty-six, for five hundred thirty-seven point three million dollars. That''s the largest single change order in the project''s history.', 13, 623.0, '10:23', 200, '2026-10-24T18:08:00Z')
