INSERT INTO sources (episode_id, episode_slug, sort_order, title, url, publisher, domain, published_date, description, quote, turn_index, timestamp_seconds, timestamp_label, http_status, verified_at) VALUES ((SELECT id FROM episodes WHERE slug = 'california-high-speed-rail-and-the-billionaire-tax'), 'california-high-speed-rail-and-cap-and-trade', 4, 'New Cost Estimate for California High-Speed Rail Puts Bullet Train $100 Billion in the Red', 'https://www.latimes.com/california/story/2023-03-11/new-cost-estimate-for-high-speed-rail-puts-california-bullet-train-100-billion-in-the-red', 'Los Angeles Times', 'latimes.com', NULL, 'News coverage examining the escalating $35.3 billion cost estimate and 2030–2033 schedule window for the Merced–to–Bakersfield operating segment alongside the $128 billion Phase 1 price tag.', 'The three civil works contracts started at two point eight billion and are now worth nine point three billion — mostly change orders, but the base price already includes the contractor''s design fees.', 21, 850.0, '14:10', 200, '2026-10-24T18:08:00Z')
