INSERT INTO sources (episode_id, episode_slug, sort_order, title, url, publisher, domain, published_date, description, quote, turn_index, timestamp_seconds, timestamp_label, http_status, verified_at) VALUES ((SELECT id FROM episodes WHERE slug = 'california-high-speed-rail-and-the-billionaire-tax'), 'california-high-speed-rail-and-cap-and-trade', 5, 'High-Speed Rail Draft 2026 Business Plan: Legislative Analyst''s Office Review of Cap-and-Trade Funding', 'https://lao.ca.gov/handouts/transportation/2026/High-Speed-Rail-Draft-2026-Business-Plan-042726.pdf', 'California Legislative Analyst''s Office (LAO)', 'lao.ca.gov', NULL, 'Nonpartisan LAO fiscal review evaluating HSRA''s reliance on $1 billion annual Greenhouse Gas Reduction Fund (Cap-and-Trade) appropriations, securitization borrowing proposals, and the Merced–Bakersfield funding gap.', 'Start with a cap-and-trade auction dollar hitting the authority''s account. About sixty cents of it goes toward the Merced-to-Bakersfield early operating segment — that''s the thirty-five point seven billion budget for the first hundred nineteen miles.', 27, 979.0, '16:19', 200, '2026-10-24T18:08:00Z')
