INSERT INTO sources (episode_id, episode_slug, sort_order, title, url, publisher, domain, published_date, description, quote, turn_index, timestamp_seconds, timestamp_label, http_status, verified_at) VALUES ((SELECT id FROM episodes WHERE slug = 'california-high-speed-rail-and-the-billionaire-tax'), 'california-high-speed-rail-and-cap-and-trade', 6, 'Proposition 1 (2024): Behavioral Health Services Program and Bond Measure — Official Ballot Text of Proposed Law', 'https://vig.cdn.sos.ca.gov/2024/primary/pdf/topl.pdf', 'California Secretary of State', 'vig.cdn.sos.ca.gov', NULL, 'Official March 5, 2024 primary election Text of Proposed Law for Proposition 1 authorizing $6.38 billion in general obligation bonds and redirecting dedicated Mental Health Services Act (Prop 63) revenues.', 'In two thousand nine, Prop one-D tried to shift two hundred sixty-eight million a year from First Five early-childhood programs to the general fund, and Prop one-E tried to borrow Prop sixty-three mental health money for two years. Both lost. The pattern is that voters treat earmarked funds as sacred even when they don''t love the program behind them.', 43, 1521.0, '25:21', 200, '2026-10-24T18:08:00Z')
