INSERT INTO source_spans (source_id, turn_index, start_offset, end_offset, quote) VALUES ((SELECT id FROM sources WHERE episode_id = (SELECT id FROM episodes WHERE slug = 'california-high-speed-rail-and-the-billionaire-tax') AND url = 'https://vig.cdn.sos.ca.gov/2024/primary/pdf/topl.pdf'), 43, 755, 1107, 'In two thousand nine, Prop one-D tried to shift two hundred sixty-eight million a year from First Five early-childhood programs to the general fund, and Prop one-E tried to borrow Prop sixty-three mental health money for two years. Both lost. The pattern is that voters treat earmarked funds as sacred even when they don''t love the program behind them.')
